pub struct OriginalCheckpointRoute{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,roster:ChildRosterIdentity,args:ManuallyDrop<Option<DslValue>>,receiving:ManuallyDrop<Option<Box<OriginalPackReceiving<OriginalCheckpointArguments>>>>,arguments:ManuallyDrop<Option<OriginalCheckpointArguments>>,metadata:ManuallyDrop<Option<CheckpointMetadata>>,cascade:ManuallyDrop<Option<Box<ChildCheckpointCascade>>>,bundle:ManuallyDrop<Option<(CheckpointMetadata,Vec<CompositionPin>,bool)>>,pins:ManuallyDrop<Option<Vec<CompositionPin>>>,probe:OriginalPendingEditIds,request:ManuallyDrop<Option<ArtifactNativeVcsRequest>>,command:ManuallyDrop<Option<Box<ChildVcsCommandUnit>>>,result:Option<ArtifactNativeVcsResult>,retirement:RetainedCloneClose,phase:u8,dirty:bool,children_changed:bool,closing:bool}
