 pub fn admit(args:&mut Option<DslValue>,roster:ChildRosterIdentity,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::capture_demands();admit_original_construction(cx,output,original(d),|control|Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,roster,args:ManuallyDrop::new(args.take()),receiving:ManuallyDrop::new(None),arguments:ManuallyDrop::new(None),metadata:ManuallyDrop::new(None),cascade:ManuallyDrop::new(None),bundle:ManuallyDrop::new(None),pins:ManuallyDrop::new(None),probe:OriginalPendingEditIds::probe(),request:ManuallyDrop::new(None),command:ManuallyDrop::new(None),result:None,retirement:Default::default(),phase:0,dirty:false,children_changed:false,closing:false}),paid(d))))}
