 pub fn advance<C:SpaceMember,P:SpaceMember>(&mut self,roster:ChildRosterIdentity,mut child:Option<&mut C>,parent:&mut P,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if self.closing||cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original reserved checkpoint was cancelled").into())}match self.phase{
 0=>{if self.args.is_some(){if OriginalPackReceiving::admit_value(&mut self.args,cx,&mut self.receiving)?{self.phase=1;}}else{let d=header::<(OriginalCheckpointArguments,u8)>();self.action(cx,d,|s|{*s.arguments=Some(OriginalCheckpointArguments{message:None,authors:Vec::new()});s.phase=3;Ok(())})?;}},
 1=>{if self.receiving.as_mut().unwrap().advance(cx)?{self.phase=2;}},
 2=>{if self.receiving.as_mut().unwrap().take(cx,&mut self.arguments)?{self.phase=3;}},
 3=>{if self.close_receiving(cx)?{self.action(cx,header::<u8>(),|s|{s.phase=4;Ok(())})?;}},
 4=>{if let Some(dirty)=self.probe.pending_found(){if !dirty&&parent.native_checkpoint_id().is_none()&&self.roster.2!=0{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"an initial composition checkpoint requires its original pending parent edit").into())}self.action(cx,header::<(CheckpointMetadata,OriginalCheckpointArguments,bool,u8)>(),|s|{let args=s.arguments.take().ok_or_else(invalid)?;*s.metadata=Some((args.message,args.authors));s.dirty=dirty;s.phase=5;Ok(())})?;}else{let d=parent.native_checkpoint_probe_demands(&self.probe)?;let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|Ok(((),parent.advance_native_checkpoint_probe(&mut self.probe,g)?)))?;}},
 5=>{if ChildCheckpointCascade::admit(&mut self.metadata,roster,cx,&mut self.cascade)?{self.phase=6;}},
 6=>{if self.cascade.as_mut().unwrap().advance(roster,child.as_deref_mut(),cx)?{self.phase=7;}},
 7=>{if self.cascade.as_mut().unwrap().take(roster,cx,&mut self.bundle)?{self.phase=8;}},
 8=>{if self.close_cascade(roster,child.as_deref_mut(),cx)?{self.action(cx,header::<(CheckpointMetadata,Vec<CompositionPin>,bool,u8)>(),|s|{let(metadata,pins,changed)=s.bundle.take().ok_or_else(invalid)?;s.children_changed=changed;*s.metadata=Some(metadata);*s.pins=Some(pins);s.phase=9;Ok(())})?;}},
 9=>{if self.dirty{self.action(cx,header::<(CheckpointMetadata,ArtifactNativeVcsRequest,u8)>(),|s|{let(message,authors)=s.metadata.take().ok_or_else(invalid)?;*s.request=Some(ArtifactNativeVcsRequest::CommitCheckpoint{message,authors});s.phase=10;Ok(())})?;}else{self.action(cx,header::<u8>(),|s|{s.phase=12;Ok(())})?;}},
 10=>{if ChildVcsCommandUnit::admit(&mut self.request,cx,&mut self.command)?{self.phase=11;}},
 11=>{let command=self.command.as_mut().unwrap();if !command.ready(){command.advance(parent,cx)?;}else if command.take_result(cx,&mut self.result)?{self.phase=12;}},
 12=>{if !self.close_parent(parent,cx)?{return Ok(false)}if !self.probe.terminal_is_empty(){let d=self.probe.close_demands(self.body)?;close_original_retained_step(cx,d,|g|self.probe.close_step(g))?;return Ok(false)}if self.metadata.is_some()||!self.retirement.is_empty(){let d=self.retirement.next_owner_demands::<CheckpointMetadata>(self.metadata.is_some(),&None,self.body)?;close_original_retained_step(cx,d,|g|if !self.retirement.is_empty(){self.retirement.select(self.body)?.step(g)}else{Ok(self.retirement.begin_granted(&mut self.metadata,g)?.ok_or_else(invalid)?)})?;return Ok(false)}self.action(cx,header::<u8>(),|s|{s.phase=13;Ok(())})?;},
 13=>{self.action(cx,header::<Option<ArtifactNativeVcsResult>>(),|s|{s.result=None;s.phase=14;Ok(())})?;},14=>{},_=>return Err(invalid().into()),}Ok(self.ready())}
 pub fn take(&mut self,roster:ChildRosterIdentity,cx:&mut StepContext<'_>,output:&mut Option<(bool,Vec<CompositionPin>)>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if !self.ready(){return Err(invalid().into())}let d=header::<(bool,Vec<CompositionPin>,u8)>();admit_original_construction(cx,output,original(d),|_|{self.phase=15;let pins=self.pins.take().ok_or_else(invalid)?;Ok(((self.dirty||self.children_changed,pins),paid(d)))})}
 fn close_receiving(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(receiver)=self.receiving.as_mut()else{return Ok(true)};if !receiver.terminal_is_empty(){cx.with_original_retirement(|cx|receiver.close_step(cx))?;return Ok(false)}let mut d=OriginalPackReceiving::<OriginalCheckpointArguments>::release_demands();d.copy_bytes=size_of::<Option<Box<OriginalPackReceiving<OriginalCheckpointArguments>>>>();close_original_retained_step(cx,d,|_|{self.receiving.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;Ok(false)}
 fn close_cascade<C:SpaceMember>(&mut self,roster:ChildRosterIdentity,child:Option<&mut C>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(cascade)=self.cascade.as_mut()else{return Ok(true)};if !cascade.terminal_is_empty(){cx.with_original_retirement(|cx|cascade.close_step(roster,child,cx))?;return Ok(false)}let mut d=ChildCheckpointCascade::release_demands();d.copy_bytes=size_of::<Option<Box<ChildCheckpointCascade>>>();close_original_retained_step(cx,d,|_|{self.cascade.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;Ok(false)}
 fn close_parent<P:SpaceMember>(&mut self,parent:&mut P,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(command)=self.command.as_mut()else{return Ok(true)};if !command.terminal_is_empty(){cx.with_original_retirement(|cx|command.close_step(parent,cx))?;return Ok(false)}let mut d=ChildVcsCommandUnit::release_demands();d.copy_bytes=size_of::<Option<Box<ChildVcsCommandUnit>>>();close_original_retained_step(cx,d,|_|{self.command.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;Ok(false)}
 pub fn close_demands<C:SpaceMember,P:SpaceMember>(&self,child:Option<&C>,parent:&P)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if let Some(receiver)=self.receiving.as_ref(){return if receiver.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<OriginalPackReceiving<OriginalCheckpointArguments>>>>(),..OriginalPackReceiving::<OriginalCheckpointArguments>::release_demands()})}else{receiver.close_demands()}}if let Some(cascade)=self.cascade.as_ref(){return if cascade.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<ChildCheckpointCascade>>>(),..ChildCheckpointCascade::release_demands()})}else{cascade.close_demands(child)}}if let Some(command)=self.command.as_ref(){return if command.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<ChildVcsCommandUnit>>>(),..ChildVcsCommandUnit::release_demands()})}else{command.close_demands(parent)}}if !self.probe.terminal_is_empty(){return self.probe.close_demands(self.body)}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}macro_rules! field{($f:ident,$t:ty)=>{if self.$f.is_some(){return self.retirement.next_owner_demands::<$t>(true,&None,self.body)}};}field!(args,DslValue);field!(arguments,OriginalCheckpointArguments);field!(metadata,CheckpointMetadata);field!(bundle,(CheckpointMetadata,Vec<CompositionPin>,bool));field!(pins,Vec<CompositionPin>);field!(request,ArtifactNativeVcsRequest);if self.result.is_some(){return Ok(header::<Option<ArtifactNativeVcsResult>>())}Ok(Default::default())}
 pub fn close_step<C:SpaceMember,P:SpaceMember>(&mut self,roster:ChildRosterIdentity,mut child:Option<&mut C>,parent:&mut P,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands(child.as_deref(),parent)?;if !self.closing{close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(false)}if !self.close_receiving(cx)?||!self.close_cascade(roster,child.as_deref_mut(),cx)?||!self.close_parent(parent,cx)?{return Ok(false)}if !self.probe.terminal_is_empty(){close_original_retained_step(cx,d,|g|self.probe.close_step(g))?;return Ok(false)}close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}macro_rules! field{($f:ident)=>{if self.$f.is_some(){return Ok(self.retirement.begin_granted(&mut self.$f,g)?.ok_or_else(invalid)?)}};}field!(args);field!(arguments);field!(metadata);field!(bundle);field!(pins);field!(request);self.result=None;Ok(RetainedCloneStep::Progress(paid(d)))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.args.is_none()&&self.receiving.is_none()&&self.arguments.is_none()&&self.metadata.is_none()&&self.cascade.is_none()&&self.bundle.is_none()&&self.pins.is_none()&&self.request.is_none()&&self.command.is_none()&&self.result.is_none()&&self.probe.terminal_is_empty()&&self.retirement.is_empty()}
